\"\"\"Minimal OpenAI Responses API client using only Python's standard library.

Prompts are sent over HTTPS with "'``store=False`` so responses are not retained
by the API. The optional command-line interface reads the prompt from stdin,
avoiding shell history and process-list exposure.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from collections.abc import Mapping
from typing import Any
from urllib import error, request


DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"
DEFAULT_TIMEOUT = 120.0


class OpenAIError(RuntimeError):
    """Raised when the Responses API cannot complete a request."""

    def __init__(
        self,
        message: str,
        *,
        status_code: int | None = None,
        error_type: str | None = None,
        code: str | None = None,
        request_id: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.error_type = error_type
        self.code = code
        self.request_id = request_id


class OpenAIResponseError(OpenAIError):
    """Raised when a successful API response contains no output text."""


class OpenAIClient:
    """Send text prompts to OpenAI'"'s Responses API.\"\"\"

    def __init__(
        self,
        *,
        api_key: str | None = None,
        model: str | None = None,
        endpoint: str = DEFAULT_ENDPOINT,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> None:
        resolved_api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not resolved_api_key:
            raise ValueError(
                \"No API key provided; pass api_key or set OPENAI_API_KEY.\"
            )
        if not endpoint.startswith(\"https://\"):
            raise ValueError(\"The Responses API endpoint must use HTTPS.\")
        if timeout <= 0:
            raise ValueError(\"timeout must be greater than zero\")

        self.api_key = [REDACTED_SECRET]
        self.model = model or os.environ.get(\"OPENAI_MODEL\")
        self.endpoint = endpoint
        self.timeout = timeout

    def send_prompt(
        self,
        prompt: str,
        *,
        model: str | None = None,
        max_output_tokens: int | None = None,
        timeout: float | None = None,
    ) -> str:
        \"\"\"Send a text prompt and return the response's output text.\"\"\"
        response = self.create_response(
            prompt,
            model=model,
            max_output_tokens=max_output_tokens,
            timeout=timeout,
        )
        return self._extract_output_text(response)

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        max_output_tokens: int | None = None,
        timeout: float | None = None,
    ) -> dict[str, Any]:
        \"\"\"Send a text prompt and return the complete JSON response.\"\"\"
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError(\"prompt must be a non-empty string\")

        selected_model = model or self.model
        if not selected_model:
            raise ValueError(
                \"No model provided; pass model or set OPENAI_MODEL.\"
            )

        selected_timeout = timeout if timeout is not None else self.timeout
        if selected_timeout <= 0:
            raise ValueError(\"timeout must be greater than zero\")

        if max_output_tokens is not None:
            if (
                isinstance(max_output_tokens, bool)
                or not isinstance(max_output_tokens, int)
                or max_output_tokens <= 0
            ):
                raise ValueError(\"max_output_tokens must be a positive integer\")

        payload: dict[str, Any] = {
            \"model\": selected_model,
            \"input\": prompt,
            \"store\": False,
        }
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = max_output_tokens

        api_request = request.Request(
            self.endpoint,
            data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
                \"User-Agent\": \"openai-client/1.0\",
            },
            method=\"POST\",
        )

        try:
            with request.urlopen(api_request, timeout=selected_timeout) as response:
                response_body = response.read()
        except error.HTTPError as exc:
            raise self._http_error(exc) from None
        except (error.URLError, TimeoutError, OSError) as exc:
            reason = getattr(exc, \"reason\", exc)
            raise OpenAIError(f\"Could not reach the OpenAI API: {reason}\") from None

        try:
            decoded_response = json.loads(response_body)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIError(
                \"The OpenAI API returned an invalid JSON response.\"
            ) from exc
        if not isinstance(decoded_response, dict):
            raise OpenAIError(\"The OpenAI API returned an unexpected JSON value.\")
        return decoded_response

    @staticmethod
    def _http_error(exc: error.HTTPError) -> OpenAIError:
        try:
            body = exc.read()
            decoded = json.loads(body)
        except (UnicodeDecodeError, json.JSONDecodeError):
            decoded = None

        api_error: Mapping[str, Any] = {}
        if isinstance(decoded, Mapping):
            possible_error = decoded.get(\"error\")
            if isinstance(possible_error, Mapping):
                api_error = possible_error

        message = api_error.get(\"message\")
        if not isinstance(message, str) or not message:
            message = f\"OpenAI API request failed with HTTP status {exc.code}.\"

        error_type = api_error.get(\"type\")
        code = api_error.get(\"code\")
        return OpenAIError(
            message,
            status_code=exc.code,
            error_type=error_type if isinstance(error_type, str) else None,
            code=code if isinstance(code, str) else None,
            request_id=exc.headers.get(\"x-request-id\") if exc.headers else None,
        )

    @staticmethod
    def _extract_output_text(response: Mapping[str, Any]) -> str:
        output = response.get(\"output\")
        if not isinstance(output, list):
            output = []

        text_parts: list[str] = []
        for output_item in output:
            if not isinstance(output_item, Mapping):
                continue
            content = output_item.get(\"content\")
            if not isinstance(content, list):
                continue
            for content_item in content:
                if not isinstance(content_item, Mapping):
                    continue
                if content_item.get(\"type\") "'!= "output_text":
                    continue
                text = content_item.get("text")
                if isinstance(text, str):
                    text_parts.append(text)

        if not text_parts:
            raise OpenAIResponseError(
                "The OpenAI API response contained no output text."
            )
        return "".join(text_parts)


def main(argv: list[str] | None = None) -> int:
    """Read a prompt from stdin, print the model response, and return an exit code."""
    parser = argparse.ArgumentParser(
        description=(
            "Send a private text prompt to OpenAI'"'s Responses API. \"
            \"The prompt is read from standard input.\"
        )
    )
    parser.add_argument(
        \"--model\",
        help=\"model to use (defaults to OPENAI_MODEL)\",
    )
    parser.add_argument(
        \"--max-output-tokens\",
        type=int,
        help=\"maximum number of output tokens\",
    )
    args = parser.parse_args(argv)

    prompt = sys.stdin.read()
    if not prompt.strip():
        parser.error(\"provide a prompt on standard input\")

    try:
        client = OpenAIClient(model=args.model)
        print(
            client.send_prompt(
                prompt,
                max_output_tokens=args.max_output_tokens,
            )
        )
    except (ValueError, OpenAIError) as exc:
        print(f\"Error: {exc}\", file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
